import {attr, controller, target} from '@github/catalyst'
import {debounce} from '@github/mini-throttle/decorators'
import {verifiedFetch} from '@github-ui/verified-fetch'

@controller('entity-lookup')
export class EntityLookupElement extends HTMLElement {
  @target declare input: HTMLInputElement
  @target declare result: HTMLElement

  @attr lookupUrl = ''
  @attr entityType = ''

  #abortController: AbortController | null = null

  @debounce(400)
  scheduleLookup() {
    void this.#doLookup()
  }

  async #doLookup() {
    const id = parseInt(this.input.value, 10)

    if (!id || id <= 0) {
      this.#abortController?.abort()
      this.#abortController = null
      this.result.textContent = ''
      return
    }

    this.#abortController?.abort()
    const abortController = (this.#abortController = new AbortController())
    const {signal} = abortController

    const url = `${this.lookupUrl}?entity_type=${encodeURIComponent(this.entityType)}&entity_id=${encodeURIComponent(id)}`

    try {
      const response = await verifiedFetch(url, {
        signal,
        headers: {
          Accept: 'text/html',
          'X-Requested-With': 'XMLHttpRequest',
        },
      })

      if (signal.aborted) return

      if (response.ok) {
        // eslint-disable-next-line @github-ui/github-monorepo/require-set-sanitized-inner-html -- assigns server-rendered HTML (string) fetched from a trusted endpoint
        this.result.innerHTML = await response.text()
      } else {
        this.#showError()
      }
    } catch {
      if (signal.aborted) return
      this.#showError()
    } finally {
      if (this.#abortController === abortController) {
        this.#abortController = null
      }
    }
  }

  disconnectedCallback() {
    this.#abortController?.abort()
    this.#abortController = null
  }

  #showError() {
    this.result.textContent = ''
    const span = document.createElement('span')
    span.className = 'color-fg-danger text-bold'
    span.textContent = '⚠ Lookup failed'
    this.result.appendChild(span)
  }
}
